def handle_radar_destroyed(self, radar_id: str, sim_time: float) -> list[str]:
    radar = self.radar_reg.get(radar_id)
    if radar:
        radar.state = RadarState.DESTROYED

    orphaned = self.missile_reg.by_radar(radar_id)
    reassigned: list[str] = []

    for missile in orphaned:
        missile.guiding_radar_id = None
        if missile.id in self.connections:
            self.connections[missile.id].transition(ConnectionState.FAILED)

        new_radar = self._find_best_radar(missile)
        if new_radar is not None:
            if self.iff.check_entity(missile.iff_code):
                self.connect(new_radar, missile, sim_time)
                reassigned.append(missile.id)
                logger.info(f"Failover: {missile.spec.name} [{missile.id}] "
                           f"-> {new_radar.spec.name} [{new_radar.id}]")
        else:
            if missile.can_go_autonomous:
                missile.state = MissileState.AUTONOMOUS
                logger.info(f"Missile {missile.id} entering autonomous mode")
            else:
                missile.state = MissileState.LOST
                logger.warning(f"Missile {missile.id} LOST - no radar, no seeker")

    return reassigned
